public IEnumerable<int> Evens(int max)
{
    for (long i = 0; i <= max; i += 2)
        yield return (int)i;
}

public Dictionary<char, int> CountLetters(string text)
{
    var counts = new Dictionary<char, int>();
    foreach (var c in text)
    {
        if (!char.IsLetter(c)) continue;
        var key = char.ToLowerInvariant(c);
        counts[key] = counts.GetValueOrDefault(key) + 1;
    }
    return counts;
}

public Dictionary<string, int> TotalsByCustomer(IEnumerable<Order> orders) =>
    orders.GroupBy(o => o.Customer)
          .ToDictionary(g => g.Key, g => g.Sum(o => o.Total));

