public T MaxBy<T>(IEnumerable<T> items, Func<T, int> key)
{
    using var e = items.GetEnumerator();
    if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements.");
    T best = e.Current;
    int bestKey = key(best);
    while (e.MoveNext())
    {
        int k = key(e.Current);
        if (k > bestKey) { best = e.Current; bestKey = k; } // > keeps the first on a tie
    }
    return best;
}

public bool IsPalindrome(string s)
{
    int i = 0, j = s.Length - 1;
    while (i < j)
    {
        if (!char.IsLetterOrDigit(s[i])) { i++; continue; }
        if (!char.IsLetterOrDigit(s[j])) { j--; continue; }
        if (char.ToLowerInvariant(s[i]) != char.ToLowerInvariant(s[j])) return false;
        i++; j--;
    }
    return true;
}
